/* ------------------------------------------------------------------ */
/* Investment Thesis card                                              */
/* ------------------------------------------------------------------ */

function formatINR(v) {
  if (v >= 10000000) return `₹${(v / 10000000).toFixed(v % 10000000 === 0 ? 0 : 1)} Cr`;
  if (v >= 100000) return `₹${(v / 100000).toFixed(v % 100000 === 0 ? 0 : 1)} L`;
  return `₹${v.toLocaleString("en-IN")}`;
}

function InvestmentThesisCard({ selectedSectors, toggleSector, ticket, setTicket, selectedStages, toggleStage }) {
  const min = 100000, max = 100000000; // ₹1 Lakh – ₹10 Crore
  const pct = (v) => ((v - min) / (max - min)) * 100;

  return (
    <div className="ayush-floating-card h-full">
      <h2 className="mb-6 text-sm font-bold uppercase tracking-wide text-[#21281E]">Investment Thesis / Interest Profile</h2>
      <div className="mb-8">
        <p className="ayush-muted mb-3 text-xs font-semibold uppercase tracking-wide">Sector Tags</p>
        <div className="flex flex-wrap gap-2">
          {SECTOR_TAGS.map((tag) => {
            const active = selectedSectors.includes(tag);
            return (
              <button
                key={tag}
                onClick={() => toggleSector(tag)}
                className={`rounded-full px-4 py-1.5 text-xs font-bold uppercase tracking-wide transition-colors ${active ? "ayush-pill-active shadow-sm" : "ayush-pill hover:bg-white"}`}
              >
                {tag}
              </button>
            );
          })}
        </div>
      </div>

      <div className="mb-8">
        <p className="ayush-muted mb-4 text-xs font-semibold uppercase tracking-wide">Ticket Size</p>
        <div className="relative h-1.5 rounded-full" style={{ background: "#E3D6AC" }}>
          <div
            className="absolute h-1.5 rounded-full shadow-sm"
            style={{ left: `${pct(ticket[0])}%`, right: `${100 - pct(ticket[1])}%`, background: "#1E5B3A" }}
          />
          <input
            type="range" min={min} max={max} step={100000} value={ticket[0]}
            onChange={(e) => setTicket([Math.min(Number(e.target.value), ticket[1] - 100000), ticket[1]])}
            className="dual-range absolute inset-0 w-full"
          />
          <input
            type="range" min={min} max={max} step={100000} value={ticket[1]}
            onChange={(e) => setTicket([ticket[0], Math.max(Number(e.target.value), ticket[0] + 100000)])}
            className="dual-range absolute inset-0 w-full"
          />
        </div>
        <div className="mt-3 flex justify-between text-sm font-bold text-[#21281E]">
          <span className="rounded-md bg-white px-2 py-1 shadow-sm border border-[#E3D6AC]">{formatINR(ticket[0])}</span>
          <span className="rounded-md bg-white px-2 py-1 shadow-sm border border-[#E3D6AC]">{formatINR(ticket[1])}</span>
        </div>
      </div>

      <div>
        <p className="ayush-muted mb-3 text-xs font-semibold uppercase tracking-wide">Stage Preference</p>
        <div className="flex flex-col gap-3">
          {STAGES.map((stage) => {
            const checked = selectedStages.includes(stage);
            return (
              <label key={stage} className="flex cursor-pointer items-center gap-3 text-sm font-medium hover:text-[#1E5B3A] transition-colors">
                <span
                  onClick={() => toggleStage(stage)}
                  className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md transition-colors"
                  style={{ border: "1px solid #C9BB90", background: checked ? "#1E5B3A" : "#fff", borderColor: checked ? "#1E5B3A" : "#C9BB90" }}
                >
                  {checked && <Check className="h-3.5 w-3.5 text-white" strokeWidth={3} />}
                </span>
                {stage}
              </label>
            );
          })}
        </div>
      </div>
    </div>
  );
}

