export default function InvestorDashboardPage({ investorName }) {
  const [selectedSectors, setSelectedSectors] = useState(["Ayurveda"]);
  const [selectedStages, setSelectedStages] = useState([]);
  const [ticket, setTicket] = useState([1000000, 50000000]); // ₹10 Lakh – ₹5 Crore
  const [activeTab, setActiveTab] = useState("Overview");
  const savedProfile = (() => {
    try {
      const data = localStorage.getItem("ayush_user_profile");
      return data ? JSON.parse(data) : null;
    } catch {
      return null;
    }
  })();
  const displayName = investorName || savedProfile?.user?.fullName || savedProfile?.user?.username || savedProfile?.user?.email || "Investor";

  const toggleSector = (tag) => setSelectedSectors((prev) => (prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]));
  const toggleStage = (stage) => setSelectedStages((prev) => (prev.includes(stage) ? prev.filter((s) => s !== stage) : [...prev, stage]));

  return (
    <div
      className="ayush-page min-h-screen"
      style={{
        backgroundImage: `linear-gradient(90deg, rgba(242,232,206,0.97) 0%, rgba(242,232,206,0.85) 30%, rgba(242,232,206,0.35) 60%, rgba(242,232,206,0.05) 100%), url(${heroBg})`,
        backgroundSize: "cover",
        backgroundPosition: "top right",
        backgroundRepeat: "no-repeat",
        backgroundAttachment: "fixed",
      }}
    >
      <Theme />
      <div className="px-6 pt-6 sm:px-10">
        <a
          href="http://localhost:5000?skipIntro=true"
          className="ayush-btn-solid inline-flex items-center gap-2 rounded-full px-4 py-2 text-sm font-semibold shadow-sm"
        >
          <ArrowRight className="h-4 w-4 rotate-180" /> Back to Home
        </a>
      </div>

      <main className="mx-auto max-w-[1400px] px-6 py-8 sm:px-10">
        <div className="mb-8 flex flex-col items-center">
          <h1 className="text-center text-2xl font-extrabold uppercase tracking-wide text-[#21281E] sm:text-3xl">
            Investor Dashboard
          </h1>
          <p className="mt-1 text-base font-semibold text-[#4D4637] sm:text-lg">
            Welcome, {displayName}
          </p>
        </div>

        <div className="sticky top-6 z-20 mb-10 flex justify-center">
          <div className="ayush-nav-container flex gap-2 overflow-x-auto" role="tablist" aria-label="Investor dashboard sections">
            {["Overview", "My Startups", "Connections", "Portfolio"].map((tab) => (
              <button
                key={tab}
                type="button"
                role="tab"
                aria-selected={activeTab === tab}
                onClick={() => setActiveTab(tab)}
                className={`text-sm shrink-0 ${
                  activeTab === tab
                    ? "ayush-nav-pill-active ayush-nav-pill"
                    : "ayush-nav-pill"
                }`}
              >
                {tab}
              </button>
            ))}
          </div>
        </div>

        {activeTab === "Overview" && (
          <div className="flex flex-col gap-8 lg:flex-row">
            <div className="w-full lg:w-[35%]">
              <InvestmentThesisCard
                selectedSectors={selectedSectors}
                toggleSector={toggleSector}
                ticket={ticket}
                setTicket={setTicket}
                selectedStages={selectedStages}
                toggleStage={toggleStage}
              />
            </div>
            <div className="w-full lg:w-[65%]">
              <MatchedStartupFeed />
            </div>
          </div>
        )}

        {activeTab === "My Startups" && <ShortlistedStartupsCard />}
        {activeTab === "Connections" && <ConnectionRequestInbox />}
        {activeTab === "Portfolio" && <PortfolioView />}

        <div className="mt-10 grid w-full min-w-0 max-w-full grid-cols-1 gap-4 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 lg:gap-6">
          <div className="ayush-floating-card flex w-full min-w-0 items-center gap-4">
            <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-[#1E5B3A] text-white">
              <Bookmark className="h-5 w-5" />
            </div>
            <div className="min-w-0 flex-1">
              <p className="break-words whitespace-normal text-xs font-semibold uppercase tracking-wide text-[#77694E]">Total Shortlisted</p>
              <p className="text-2xl font-bold">{SHORTLISTED.length}</p>
              <p className="break-words whitespace-normal text-sm text-[#77694E]">Startups</p>
            </div>
          </div>
          <div className="ayush-floating-card flex w-full min-w-0 items-center gap-4">
            <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-[#1E5B3A] text-white">
              <MessageCircle className="h-5 w-5" />
            </div>
            <div className="min-w-0 flex-1">
              <p className="break-words whitespace-normal text-xs font-semibold uppercase tracking-wide text-[#77694E]">Connection Requests</p>
              <p className="text-2xl font-bold">{CONNECTION_REQUESTS.length}</p>
              <p className="break-words whitespace-normal text-sm text-[#77694E]">New requests</p>
            </div>
          </div>
          <div className="ayush-floating-card flex w-full min-w-0 items-center gap-4">
            <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-[#1E5B3A] text-white">
              <span className="text-lg font-bold">₹</span>
            </div>
            <div className="min-w-0 flex-1">
              <p className="break-words whitespace-normal text-xs font-semibold uppercase tracking-wide text-[#77694E]">Portfolio Value</p>
              <p className="text-2xl font-bold">{PORTFOLIO.length}</p>
              <p className="break-words whitespace-normal text-sm text-[#77694E]">Investments</p>
            </div>
          </div>
        </div>
      </main>

    </div>
  );
}
